func TestResponsesNonStreamProfileTurnIsWatchable(t *testing.T) {
	turn := &watchedTurn{started: make(chan struct{}), release: make(chan struct{})}
	_, srv, _ := testHTTPServerPersistWithRunner(t, turn.runner())
